UPDATE rtu_info
SET RTU_ID=#{rtuId}
	, AREA_CODE=#{areaCode}
	, COMBI_TYPE=#{combiType}
	, RTU_TYPE=#{rtuType}
	, ORGAN_ID=#{organId}
	, SIGNAL_ID=#{signalId}
	, RTU_NAME=#{rtuName}
	, LINE_NO=#{lineNo}
	, MODEL_NO=#{modelNo}
	, CONNECTION_INFO=#{connectionInfo}
	, PORT=#{port}
	, BAUDRATE=#{baudrate}
	, SORT_FLAG=#{sortFlag}
	, RTU_STATE=#{rtuState}
	, AMP_STATE=#{ampState}
	, EQUIP_SEQ=#{equipSeq}
	, LTE_CONNECTION=#{lteConnection}
	, CALL_LAST=#{callLast}
	, EVENT_QTAIL=#{eventQtail}
	, WARNING_SMS=#{warningSms}
	, DANGER_SMS=#{dangerSms}
	, REG_DATE=#{regDate}
	, VHF_USE=#{vhfUse}
	, VHF_SYSTEM_ID=#{vhfSystemId}
	, VHF_RTU_ID=#{vhfRtuId}
	, VHF_TRANS_ID=#{vhfTransId}
	, BROADCAST_SETTING=#{broadcastSetting}
	, PRIORITY=#{priority}
	, SMARTPOWER=#{smartpower}
	, DSCODE=#{dscode}
	, CD_DIST_OBSV=#{cdDistObsv}
	, GB_OBSY=#{gbObsy}
	, REAL_ORGAN_CODE=#{realOrganCode}

