SELECT RTU_ID , AREA_CODE , COMBI_TYPE , RTU_TYPE , ORGAN_ID , SIGNAL_ID , RTU_NAME , LINE_NO , MODEL_NO , CONNECTION_INFO , PORT , BAUDRATE , SORT_FLAG , RTU_STATE , AMP_STATE , EQUIP_SEQ , LTE_CONNECTION , CALL_LAST , EVENT_QTAIL , WARNING_SMS , DANGER_SMS , REG_DATE , VHF_USE , VHF_SYSTEM_ID , VHF_RTU_ID , VHF_TRANS_ID , BROADCAST_SETTING , PRIORITY , SMARTPOWER , DSCODE , CD_DIST_OBSV , GB_OBSY , REAL_ORGAN_CODE FROM rtu_info WHERE 1=1
AND RTU_ID = #{searchKeyword}
AND AREA_CODE LIKE CONCAT('%',#{searchKeyword},'%')
ORDER BY limit #{recordCountPerPage} offset #{firstIndex}

SELECT COUNT(*) totcnt FROM rtu_info WHERE 1=1
AND RTU_ID = #{searchKeyword}
AND AREA_CODE LIKE CONCAT('%',#{searchKeyword},'%')
